    [2545]={name="Malleable Chain Leggings",quality=2,ilvl=26,reqLevel=18,sourceType="quest_reward",instructions="Reward from the quest 'Apprentice's Duties'. Pick it over the other reward choices. Starts with James Halloran in Wetlands. Objective: Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.",zone="Wetlands",questName="Apprentice's Duties",lore="I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him..."},
    [2546]={name="Royal Frostmane Girdle",quality=2,ilvl=13,reqLevel=8,sourceType="rare_npc",instructions="Drops from Great Father Arctikus.",zone="Dun Morogh",npc="Great Father Arctikus"},
    [2547]={name="Boar Handler Gloves",quality=1,ilvl=5,reqLevel=1,sourceType="quest_reward",instructions="Reward from the quest 'Dwarven Outfitters'. Pick it over the other reward choices. Starts with Sten Stoutarm in Dun Morogh. Objective: Sten Stoutarm would like 8 pieces of Tough Wolf Meat.",zone="Dun Morogh",questName="Dwarven Outfitters",lore="You look as though you might need something to keep your hands warm, hm? I'll tell you what would help: a pair of nice, warm gloves."},
