    [9453]={name="Toxic Revenger",quality=3,ilvl=32,reqLevel=27,sourceType="boss_drop",instructions="Drops from Viscous Fallout.",zone="Gnomeregan",npc="Viscous Fallout",proc="Chance on hit: Deals 14 Nature damage every 3 sec to any enemy in an 8 yard radius around the caster for 12 sec."},
