    [9465]={name="Digmaster 5000",quality=3,ilvl=45,reqLevel=40,sourceType="world_drop",instructions="World drop around level 35-40.",reqSkills={{"Mining",175}},proc="Chance on hit: Punctures target's armor, lowering it by 100."},
    [9467]={name="Gahz'rilla Fang",quality=3,ilvl=48,reqLevel=43,sourceType="boss_drop",instructions="Drops from Gahz'rilla.",zone="Zul'Farrak",npc="Gahz'rilla",proc="Chance on hit: Deal 84 Nature damage, increased by 2% per stack of Static Electricity. Deals 2 times as much damage to Aquatic enemies."},
    [9473]={name="Jinxed Hoodoo Skin",quality=3,ilvl=49,reqLevel=44,sourceType="boss_drop",instructions="Drops from Shadowpriest Sezz'ziz.",zone="Zul'Farrak",npc="Shadowpriest Sezz'ziz"},
    [9475]={name="Diabolic Skiver",quality=3,ilvl=49,reqLevel=44,sourceType="boss_drop",instructions="Drops from Shadowpriest Sezz'ziz.",zone="Zul'Farrak",npc="Shadowpriest Sezz'ziz",proc="Chance on hit: Delivers a fatal wound for 164 to 184 Physical damage. Deals 50% increased damage to targets below 25% health."},
    [9476]={name="Big Bad Pauldrons",quality=3,ilvl=50,reqLevel=45,sourceType="boss_drop",instructions="Drops from Chief Ukorz Sandscalp.",zone="Zul'Farrak",npc="Chief Ukorz Sandscalp"},
    [9477]={name="The Chief's Enforcer",quality=3,ilvl=50,reqLevel=45,sourceType="boss_drop",instructions="Drops from Chief Ukorz Sandscalp.",zone="Zul'Farrak",npc="Chief Ukorz Sandscalp",proc="Chance on hit: Deal 294 Physical damage and stun for1.5 sec. Trolls take 2 times as much damage and stun duration."},
