    [11930]={name="The Emperor's New Cape",quality=3,ilvl=60,reqLevel=55,sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Emperor of the Dark Iron, whose ancestor's summoning of Ragnaros doomed the clan. He took Moira Bronzebeard prisoner and she chose to stay."},
    [11931]={name="Dreadforge Retaliator",quality=3,ilvl=59,reqLevel=54,sourceType="boss_drop",instructions="Drops from Emperor Dagran Thaurissan.",zone="Blackrock Depths",npc="Emperor Dagran Thaurissan",lore="Emperor of the Dark Iron, whose ancestor's summoning of Ragnaros doomed the clan. He took Moira Bronzebeard prisoner and she chose to stay.",proc="Equip: Increases your chance to Parry an attack by 1.0%."},
