    [19168]={name="Blackguard",quality=4,ilvl=70,reqLevel=60,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 300). Bought from Lokhtos Darkbargainer.",profession="Blacksmithing",proc="Equip: Increases your chance to Parry an attack by 1.0%."},
    [19169]={name="Nightfall",quality=4,ilvl=70,reqLevel=60,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 300). Bought from Lokhtos Darkbargainer.",profession="Blacksmithing",proc="Chance on hit: Spell damage taken by target increased by 15% for 5 sec."},
    [19170]={name="Ebon Hand",quality=4,ilvl=70,reqLevel=60,sourceType="profession",instructions="Crafted with Blacksmithing (requires skill 300). Bought from Lokhtos Darkbargainer.",profession="Blacksmithing",proc="Chance on hit: Sends a shadowy bolt at the enemy causing 125 to 275 Shadow damage."},
    [19302]={name="Darkmoon Ring",quality=3,ilvl=55,reqLevel=50,sourceType="vendor",instructions="Bought from Lhara.",zone="Goldshire",npc="Lhara"},
    [19324]={name="The Lobotomizer",quality=4,ilvl=65,reqLevel=60,sourceType="vendor",instructions="Bought from Gaelden Hammersmith in Stormpike Guard (Alliance) or Grunnda Wolfheart in Frostwolf Clan (Horde).",zone="Alterac Valley",npc="Gaelden Hammersmith",proc="Chance on hit: Wounds the target for 200 to 300 damage and increases the casting time of all spells by 25% for 30 sec."},
    [19491]={name="Amulet of the Darkmoon",quality=4,ilvl=65,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest '1200 Tickets - Amulet of the Darkmoon'. Starts with Gelvas Grimegate in Mulgore. Objective: ProgressStep right up, step right up! &nbsp;If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so! &nbsp;You can redeem tickets in various denominations for wondrous and fantastic prizes. &nbsp;Don't be shy, give it a try!",zone="Mulgore",questName="1200 Tickets - Amulet of the Darkmoon"},
